def build_questions(question_type: Callable[..., Any]) -> list[Any]:
    questions = []
    for question_id, section, prompt, definition, purpose, guidance, level, required, affects in _QUESTION_DATA:
        questions.append(
            question_type(
                question_id=question_id,
                section=section,
                prompt=prompt,
                definition=definition,
                purpose=purpose,
                guidance=guidance,
                required=required,
                planning_level=level,
                affects=affects,
                dependencies=_QUESTION_DEPENDENCIES.get(question_id, ()),
                examples=_QUESTION_EXAMPLES.get(question_id, ""),
                strong=_QUESTION_STRONG[question_id],
                weak=_QUESTION_WEAK[question_id],
                template=_QUESTION_TEMPLATES.get(question_id, ""),
            )
        )
    return questions
